ptx:
.version 8.7
.target sm_90a
.address_size 64

.extern .shared .align 16 .b8 global_smem[];

.visible .entry kernel(
    .param .u64 gate_ptr,
    .param .u64 value_ptr,
    .param .u64 output_ptr,
    .param .u64 dummy_ptr1,
    .param .u64 dummy_ptr2
)
{
    .reg .b64 %g,%v,%o,%off;
    .reg .b32 %t,%b,%i,%G<4>,%V<4>,%O<4>;
    .reg .b16 %h<8>,%k<8>,%z<8>;
    .reg .f32 %x<8>,%y<8>,%e<8>;

    // Each thread owns eight adjacent halves; the CTA covers 1024 elements.
    ld.param.u64 %g,[gate_ptr];
    ld.param.u64 %v,[value_ptr];
    ld.param.u64 %o,[output_ptr];
    mov.u32 %t,%tid.x;
    mov.u32 %b,%ctaid.x;
    shl.b32 %t,%t,3;
    mad.lo.u32 %i,%b,1024,%t;
    mul.wide.u32 %off,%i,2;
    add.u64 %g,%g,%off;
    add.u64 %v,%v,%off;
    add.u64 %o,%o,%off;

    // Aligned vector loads fetch all inputs; every tile is full.
    ld.global.v4.b32 {%G0,%G1,%G2,%G3},[%g];
    ld.global.v4.b32 {%V0,%V1,%V2,%V3},[%v];

    // Unpack halves and convert to single precision.
    mov.b32 {%h0,%h1},%G0;
    mov.b32 {%h2,%h3},%G1;
    mov.b32 {%h4,%h5},%G2;
    mov.b32 {%h6,%h7},%G3;
    mov.b32 {%k0,%k1},%V0;
    mov.b32 {%k2,%k3},%V1;
    mov.b32 {%k4,%k5},%V2;
    mov.b32 {%k6,%k7},%V3;
    cvt.f32.f16 %x0,%h0;
    cvt.f32.f16 %x1,%h1;
    cvt.f32.f16 %x2,%h2;
    cvt.f32.f16 %x3,%h3;
    cvt.f32.f16 %x4,%h4;
    cvt.f32.f16 %x5,%h5;
    cvt.f32.f16 %x6,%h6;
    cvt.f32.f16 %x7,%h7;
    cvt.f32.f16 %y0,%k0;
    cvt.f32.f16 %y1,%k1;
    cvt.f32.f16 %y2,%k2;
    cvt.f32.f16 %y3,%k3;
    cvt.f32.f16 %y4,%k4;
    cvt.f32.f16 %y5,%k5;
    cvt.f32.f16 %y6,%k6;
    cvt.f32.f16 %y7,%k7;

    // Compute exp(-gate) using base-two exponentials.
    mul.f32 %e0,%x0,0fBFB8AA3B;
    mul.f32 %e1,%x1,0fBFB8AA3B;
    mul.f32 %e2,%x2,0fBFB8AA3B;
    mul.f32 %e3,%x3,0fBFB8AA3B;
    mul.f32 %e4,%x4,0fBFB8AA3B;
    mul.f32 %e5,%x5,0fBFB8AA3B;
    mul.f32 %e6,%x6,0fBFB8AA3B;
    mul.f32 %e7,%x7,0fBFB8AA3B;
    ex2.approx.f32 %e0,%e0;
    ex2.approx.f32 %e1,%e1;
    ex2.approx.f32 %e2,%e2;
    ex2.approx.f32 %e3,%e3;
    ex2.approx.f32 %e4,%e4;
    ex2.approx.f32 %e5,%e5;
    ex2.approx.f32 %e6,%e6;
    ex2.approx.f32 %e7,%e7;

    // Form sigmoid reciprocals in single precision.
    add.f32 %e0,%e0,0f3F800000;
    add.f32 %e1,%e1,0f3F800000;
    add.f32 %e2,%e2,0f3F800000;
    add.f32 %e3,%e3,0f3F800000;
    add.f32 %e4,%e4,0f3F800000;
    add.f32 %e5,%e5,0f3F800000;
    add.f32 %e6,%e6,0f3F800000;
    add.f32 %e7,%e7,0f3F800000;
    rcp.approx.f32 %e0,%e0;
    rcp.approx.f32 %e1,%e1;
    rcp.approx.f32 %e2,%e2;
    rcp.approx.f32 %e3,%e3;
    rcp.approx.f32 %e4,%e4;
    rcp.approx.f32 %e5,%e5;
    rcp.approx.f32 %e6,%e6;
    rcp.approx.f32 %e7,%e7;

    // Multiply gate by sigmoid, then by value, preserving operation order.
    mul.f32 %x0,%x0,%e0;
    mul.f32 %x1,%x1,%e1;
    mul.f32 %x2,%x2,%e2;
    mul.f32 %x3,%x3,%e3;
    mul.f32 %x4,%x4,%e4;
    mul.f32 %x5,%x5,%e5;
    mul.f32 %x6,%x6,%e6;
    mul.f32 %x7,%x7,%e7;
    mul.f32 %x0,%x0,%y0;
    mul.f32 %x1,%x1,%y1;
    mul.f32 %x2,%x2,%y2;
    mul.f32 %x3,%x3,%y3;
    mul.f32 %x4,%x4,%y4;
    mul.f32 %x5,%x5,%y5;
    mul.f32 %x6,%x6,%y6;
    mul.f32 %x7,%x7,%y7;

    // Round to half precision and issue one aligned vector store.
    cvt.rn.f16.f32 %z0,%x0;
    cvt.rn.f16.f32 %z1,%x1;
    cvt.rn.f16.f32 %z2,%x2;
    cvt.rn.f16.f32 %z3,%x3;
    cvt.rn.f16.f32 %z4,%x4;
    cvt.rn.f16.f32 %z5,%x5;
    cvt.rn.f16.f32 %z6,%x6;
    cvt.rn.f16.f32 %z7,%x7;
    mov.b32 %O0,{%z0,%z1};
    mov.b32 %O1,{%z2,%z3};
    mov.b32 %O2,{%z4,%z5};
    mov.b32 %O3,{%z6,%z7};
    st.global.v4.b32 [%o],{%O0,%O1,%O2,%O3};
    ret;
}
